const picker=document.getElementById("color-picker"),hexInput=document.getElementById("hex-input"),rgbOut=document.getElementById("rgb-output"),hslOut=document.getElementById("hsl-output"),preview=document.getElementById("color-preview");function hexToRgb(t){const e=parseInt(t.slice(1,3),16),n=parseInt(t.slice(3,5),16),o=parseInt(t.slice(5,7),16);return`rgb(${e}, ${n}, ${o})`}function hexToHsl(t){let e=parseInt(t.slice(1,3),16)/255,n=parseInt(t.slice(3,5),16)/255,o=parseInt(t.slice(5,7),16)/255;const a=Math.max(e,n,o),l=Math.min(e,n,o);let u=0,r=0,s=(a+l)/2;if(a!==l){const c=a-l;switch(r=s>.5?c/(2-a-l):c/(a+l),a){case e:u=(n-o)/c+(n<o?6:0);break;case n:u=(o-e)/c+2;break;case o:u=(e-n)/c+4;break}u/=6}return`hsl(${Math.round(u*360)}, ${Math.round(r*100)}%, ${Math.round(s*100)}%)`}function update(t){if(!/^#[0-9A-Fa-f]{6}$/.test(t)){rgbOut.value="",hslOut.value="",preview.style.background="var(--bg)";return}rgbOut.value=hexToRgb(t),hslOut.value=hexToHsl(t),preview.style.background=t}picker.addEventListener("input",t=>{hexInput.value=t.target.value,update(t.target.value)}),hexInput.addEventListener("input",t=>{let e=t.target.value;e.length===7&&(picker.value=e,update(e))});function randomColor(){const t="#"+Math.floor(Math.random()*16777215).toString(16).padStart(6,"0");picker.value=t,hexInput.value=t,update(t)}function copyAll(){const t=`HEX: ${hexInput.value}
RGB: ${rgbOut.value}
HSL: ${hslOut.value}`;copyToClipboard(t).then(()=>showToast(i18n.t("common.copied")))}function downloadResult(){const t=`HEX: ${hexInput.value}
RGB: ${rgbOut.value}
HSL: ${hslOut.value}`;if(!rgbOut.value)return showToast(i18n.t("common.no_color"));downloadFile(t,"color-values.txt")}function copySingle(t){copyToClipboard(t.value).then(()=>showToast(i18n.t("common.copied")))}update("#4f46e5");
